// #bdd327 (6a993d6887e898ed58bdd327) «פיתוח: מכסת סימולציות ומעקב צריכה» — живые данные, ТОЛЬКО ЧТЕНИЕ (квоту не меняем, кандидатов не создаём).
// Кейсы QUOTA-001…QUOTA-004, QUOTA-009, QUOTA-010. Роли: менеджер аккаунта testim (auth/bizt.json), מנהל/ת מגייס/ת testim (auth/user-2.json).
// Всё сверяется с ответом rpc get_business_usage той же сессии, поэтому тесты не зависят от текущих чисел квоты. Только десктоп (L-20261014-5).
// Запрос admin_set_business_quota в QUOTA-009 — к НЕСУЩЕСТВУЮЩЕМУ бизнесу: даже при сломанной проверке роли ничего не изменится.
import { test, expect } from '@playwright/test';
import { openWithApi } from '../support/api';
import {
  HASH, MANAGER_STATE, RECRUITER_STATE, FOREIGN_ID, NO_SUCH_BUSINESS,
  fmt, currentUsage, readUsage, openInviteDrawer, footerLine,
} from './support';

const ROLES = [
  { id: 'QUOTA-003', who: 'менеджер аккаунта', state: MANAGER_STATE },
  { id: 'QUOTA-004', who: 'מנהל/ת מגייס/ת', state: RECRUITER_STATE },
];

test.describe(`Квота — менеджер аккаунта, живые данные (${HASH})`, () => {
  test.use({ storageState: MANAGER_STATE });

  test(`QUOTA-001: «הגדרות העסק» → «פרטי העסק והמכסה»: карточка квоты = get_business_usage (использовано, остаток, порог), полей изменения квоты нет @desktop @prod-safe ${HASH}`, async ({ page }) => {
    const api = await openWithApi(page, '/settings/business');
    const u = await currentUsage(api);
    await expect(page.getByText('פרטי העסק והמכסה', { exact: true }).first()).toBeVisible();
    const card = page.getByTestId('quota-card');
    await expect(card).toBeVisible();
    await expect(card.getByRole('heading', { name: /^מכסת סימולציות/ })).toBeVisible();
    await expect(card.getByTestId('quota-used')).toHaveText(fmt(u.used));
    if (u.quota === null) {
      // AC5 / S-06: квота не задана → только потребление, без блокировки.
      await expect(card.getByText(/^לא הוגדרה מכסה לחשבון, ולכן אין חסימה\./)).toBeVisible();
    } else {
      // AC1/AC6 + требование 4: менеджер видит квоту и остаток.
      await expect(card.getByText(`נוצלו מתוך ${fmt(u.quota)}`)).toBeVisible();
      await expect(card.getByText(new RegExp(`נותרו\\s+${fmt(u.remaining ?? 0)}`))).toBeVisible();
      await expect(card.getByText(new RegExp(`${u.warning_percent}%`))).toBeVisible();
    }
    // AC6: менеджер квоту не меняет — полей нет.
    await expect(card.getByRole('spinbutton')).toHaveCount(0);
    await expect(card.getByRole('textbox')).toHaveCount(0);
  });

  test(`QUOTA-002: дашборд: строка «מכסת סימולציות · נוצלו N מתוך M · נותרה/נותרו R» = get_business_usage @desktop @prod-safe ${HASH}`, async ({ page }) => {
    const api = await openWithApi(page, '/');
    const u = await currentUsage(api);
    if (u.quota === null) {
      await expect(page.getByText(/נוצלו\s+[\d,]+\s+מתוך/)).toHaveCount(0);
      test.info().annotations.push({ type: 'quota', description: 'квота не задана — строки на дашборде нет' });
      return;
    }
    // Источник: требование 4 «данные потребления в дашборде»; факт 17.11 (bdd327-bizt-dashboard-threshold-80pct).
    await expect(page.getByText('מכסת סימולציות', { exact: true }).first()).toBeVisible();
    await expect(page.getByText(new RegExp(`נוצלו\\s+${fmt(u.used)}\\s+מתוך\\s+${fmt(u.quota)}`)).first()).toBeVisible();
    await expect(page.getByText(new RegExp(`נותר[הו]\\s+${fmt(u.remaining ?? 0)}`)).first()).toBeVisible();
  });
});

for (const r of ROLES) {
  test.describe(`Квота — футер drawer «מועמד חדש», ${r.who} (${HASH})`, () => {
    test.use({ storageState: r.state });

    test(`${r.id}: drawer «מועמד חדש» (${r.who}): «נותרו N מתוך M» + «סימולציות במכסה» = get_business_usage; без квоты строки нет @desktop @prod-safe ${HASH}`, async ({ page }) => {
      const api = await openWithApi(page, '/candidates');
      const u = await currentUsage(api);
      await openInviteDrawer(page);
      if (u.quota === null) {
        // AC5: квота не задана — строки нет, блокировки нет.
        await expect(footerLine(page)).toHaveCount(0);
        return;
      }
      // Источник: реджект #bdd327 (Figma 752:1533/753:1749) + решение владельца 01.11: строка и у менеджера аккаунта, и у מגייס, и до исчерпания.
      await expect(footerLine(page)).toHaveText(new RegExp(`^נותרו\\s+${fmt(u.remaining ?? 0)}\\s+מתוך\\s+${fmt(u.quota)}$`));
      await expect(page.getByText('סימולציות במכסה', { exact: true })).toBeVisible();
      await expect(page.getByRole('button', { name: 'יצירת קישור' })).toBeVisible();
      await expect(page.getByRole('button', { name: 'ביטול' })).toBeVisible();
    });
  });
}

for (const r of [
  { who: 'менеджер аккаунта', state: MANAGER_STATE },
  { who: 'מנהל/ת מגייס/ת', state: RECRUITER_STATE },
]) {
  test.describe(`Квота — права API, ${r.who} (${HASH})`, () => {
    test.use({ storageState: r.state });

    test(`QUOTA-009: ${r.who} вызывает admin_set_business_quota → 403 forbidden (42501), квота не изменилась @desktop @prod-safe ${HASH}`, async ({ page }) => {
      const api = await openWithApi(page, '/');
      const before = await currentUsage(api);
      // Источник: AC6 / требование 6 «менеджер не может менять квоту». Цель — несуществующий бизнес, так что вызов безвреден при любом исходе.
      const res = await api.rpc('admin_set_business_quota', {
        p_business_id: NO_SUCH_BUSINESS,
        p_period_start: '2026-11-01',
        p_period_end: '2026-11-30',
        p_quota: 1,
        p_warning_percent: 80,
      });
      expect(res.status(), await res.text()).toBe(403);
      expect(await res.json()).toMatchObject({ code: '42501', message: 'forbidden' });
      const after = await currentUsage(api);
      expect({ quota: after.quota, remaining: after.remaining, warning_percent: after.warning_percent, period_start: after.period_start, period_end: after.period_end }).toEqual({
        quota: before.quota,
        remaining: before.remaining,
        warning_percent: before.warning_percent,
        period_start: before.period_start,
        period_end: before.period_end,
      });
    });

    test(`QUOTA-010: ${r.who}: get_business_usage чужого бизнеса → 403 forbidden (42501); своего id и без id — одинаковый ответ @desktop @prod-safe ${HASH}`, async ({ page }) => {
      const api = await openWithApi(page, '/');
      const own = await currentUsage(api);
      expect(own.business_id).not.toBe(FOREIGN_ID);

      // Источник: миграция 20261104100000 (чужой бизнес → 42501 forbidden), факт 17.11.
      const foreign = await api.rpc('get_business_usage', { p_business_id: FOREIGN_ID });
      expect(foreign.status(), await foreign.text()).toBe(403);
      expect(await foreign.json()).toMatchObject({ code: '42501', message: 'forbidden' });

      const sameBiz = await readUsage(await api.rpc('get_business_usage', { p_business_id: own.business_id }));
      expect({ used: sameBiz.used, quota: sameBiz.quota, remaining: sameBiz.remaining }).toEqual({ used: own.used, quota: own.quota, remaining: own.remaining });
    });
  });
}

